export const TUTORIAL_STEP_TEXTS = STEP_TEMPLATES;

export function getUiText(lang, key) {
  const l = TUTORIAL_UI[lang] ? lang : 'en';
  return (TUTORIAL_UI[l] && TUTORIAL_UI[l][key]) || TUTORIAL_UI.en[key] || key;
}

export function getStepText(lang, stepId, key) {
  const l = (STEP_TEMPLATES[stepId] && STEP_TEMPLATES[stepId][lang]) ? lang : 'en';
  return (STEP_TEMPLATES[stepId] && STEP_TEMPLATES[stepId][l] && STEP_TEMPLATES[stepId][l][key])
    || (STEP_TEMPLATES[stepId] && STEP_TEMPLATES[stepId].en && STEP_TEMPLATES[stepId].en[key])
    || '';
}

